-- GENERATED by `wfj generate` from data/quest/quest-0097.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [97003] = { "Chol'aruk il Divoratore", "Porta la testa di Chol'aruk a Gur'ak, nelle ⟦Barrens=Savane⟧.", "Ehi, tu, {class}. Mi serve il tuo aiuto. Si dice che una bestia abbia la sua tana nel fondo di una caverna ai ⟦Thorn Hill=Colli Spinosi⟧, a nord-est di qui. I ⟦Razormane=Chiomaguzza⟧ la chiamano Chol'aruk, o «il Divoratore». Pare che sia cinque volte più grossa di un normale verrospino, con una sete di sangue che non si placa mai.\n\nI più non credono a queste storie. Io sì, perché ho già combattuto contro bestie simili.\n\nTrova la sua tana e uccidi Chol'aruk. Portami la sua testa. Ma ti avverto: preparati bene e non andarci da <solo/sola>.\n\nSangue e tuono, {class}.", "Ci è voluta la forza di sei combattenti esperti per abbattere una di queste creature, e nonostante ciò è riuscita a stenderne quattro prima che potessimo finirla.\n\nSe queste bestie mostruose comparissero in numero maggiore, i danni che i verrospini potrebbero infliggere a questa terra sarebbero catastrofici.", "Notevole, {class}. Nessuno dubiterà più dei miei racconti quando tornerò a Orgrimmar con questa macabra prova dell'esistenza di questi abomini. Ma sappi che questa gloria è tua, e parlerò a gran voce delle tue imprese.\n\nLok-tar!", 0xc67797d5, 0xf7cb3419, 0x73b1b3d7, 0x4480e881, 0x8617a389, "....." },
  [97005] = { "Chol'aruk il Divoratore", "Porta la ⟦Chol'aruk's Head=Testa di Chol'aruk⟧ a Bainham, nelle ⟦Barrens=Savane⟧.", "Si dice che un abominio colossale abbia la sua tana in una caverna a nord-ovest di qui, sull'altopiano chiamato ⟦Thorn Hill=Colli Spinosi⟧. I ⟦Razormane=Chiomaguzza⟧ lo chiamano Chol'aruk, o «il Divoratore», e chi l'ha visto dice che è così enorme da poter inghiottire un orco intero.\n\nPochi credono a queste storie, ma io sì... perché ne ho affrontato uno simile con le mie mani. Sull'onore di coloro che ho perso per colpa di queste creature, questa bestia deve morire.\n\nRaduna alleati forti e trova la tana di Chol'aruk. Uccidi l'abominio e portami la sua testa.", nil, nil, 0xc67797d5, 0x5efacf98, 0xef594ded, nil, nil, "...mm" },
  [97047] = { "Il cuoco in gabbia", "Trova una chiave per la gabbia di Wendel e un travestimento con cui farlo sgattaiolare fuori, nell'Insediamento di Kurzen.", "Ehi! Tu! Devi aiutarmi! Stavo solo esplorando la giungla quando, all'improvviso, questi pazzi mi hanno teso un'imboscata! Non so cosa vogliano farmi, ma li ho sentiti parlare di tigri e di riduttori di teste, e non voglio averci niente a che fare!\n\nNon so come, ma devi tirarmi fuori di qui! Ti prego! Una chiave di questa gabbia, un travestimento per sgattaiolare via, qualcosa! Qualsiasi cosa!", nil, nil, 0x2f0f87ce, 0xcbd4ea81, 0x88f0903a, nil, nil, "...mm" },
  [97048] = { "Ritorno in porto", "Parla con la capitana Aransas alla ⟦Booty Bay=Baia del Bottino⟧.", "Senti, adesso non posso ripagarti, ma sono il cuoco della nave della capitana Aransas. Metterò di sicuro una buona parola per te quando tornerò alla ⟦Booty Bay=Baia del Bottino⟧. Dovresti parlare con la capitana appena puoi. Sono certo che sarà felice di riavermi a bordo.", nil, nil, 0xd608f137, 0x2d90b9f5, 0xaaf806d7, nil, nil, "...mm" },
  [97065] = { "Far pendere la bilancia: ⟦Keefer's Angelfish=Pesce Angelo di Keefer⟧", nil, nil, nil, nil, 0x9099a156, nil, nil, nil, nil, ".mmmm" },
  [97066] = { "Far pendere la bilancia: ⟦Brownell's Blue Striped Racer=Pesce Striato Blu di Brownell⟧", nil, nil, nil, nil, 0x8c2e8a32, nil, nil, nil, nil, ".mmmm" },
  [97067] = { "Far pendere la bilancia: ⟦Dezian Queenfish=Scienide di Dezian⟧", nil, nil, nil, nil, 0x96bb5eae, nil, nil, nil, nil, ".mmmm" },
  [97220] = { "Il favore di Philmor", "Porta la ⟦Gatehouse Shipment=Spedizione del Corpo di Guardia⟧ all'ingresso del magazzino nel negozio Trias' Cheese, nel ⟦Trade District=Quartiere del Commercio⟧.", "Per tutta la settimana siamo rimasti a corto di scaricatori.\n\nTi va di alleggerire un po' la tabella di marcia dei nostri carichi?\n\nPorta questo pacco all'ingresso del magazzino del Gatehouse. Lo trovi dentro il negozio Trias' Cheese, al piano di sopra. La padrona, Elaine, conosce bene le consegne. Al Gatehouse arrivano spesso spedizioni in modo più discreto, per permettere sorprese cerimoniali da parte degli ufficiali della guardia.", "Vuoi riempire una cassa con le nostre migliori forme stagionate?", "Oh, cielo. Pensi che vogliamo portarla su per le scale noi? Mantenere intatti gli oggetti di valore è una tua responsabilità fino al momento della consegna.", 0xcadc7a51, 0x77beb6bd, 0x756a7024, 0x0f6c2b4b, 0xfbcc083f, "....." },
  [97222] = { "Merci per il Gatehouse", "Porta la ⟦Gatehouse Shipment=Spedizione del Corpo di Guardia⟧ su per le scale del negozio di Trias e lascialo fuori dalla porta.", "Sì, è solo una rampa di scale, ma se è una richiesta così da poco, non avrai problemi a finire la consegna da te!\n\nTrias' Cheese non fa parte del Gatehouse né del suo inventario, ma i nostri edifici condividono un piano.\n\nLascia la cassa fuori dalla porta del loro magazzino: la guardia manderà qualcuno per il solito ritiro. Vedranno il pacco arrivato e lo porteranno dentro tornando al loro posto.", "Dovresti almeno assaggiare un po' di questo cheddar stagionato. Non si riesce a smettere di mangiarlo.", "Già. C'è un motivo se quel cardine apre verso l'interno, dalla loro parte: così la porta non viene bloccata da gente che lascia roba dove le pare.\n\nConsideraci in rapporti professionali, {class}.\n\nRispettiamo i tuoi affari e ci aspettiamo che tu rispetti i nostri.", 0x2ad17834, 0xd062b437, 0x4288f8d0, 0xc9e39695, 0xb35fbfba, "....." },
  [97223] = { "La matriarca dei Bloodtalon", "Porta gli Eggs of the Bloodtalon Matriarch a ⟦Xar'Ti=Xar'ti⟧, al ⟦Sen'jin Village=Villaggio di Sen'jin⟧.", "Tutti i raptor che vedi davanti a te li ho addestrati io. Vengono da ogni angolo di Kalimdor, ma alcuni dei migliori vengono dai raptor Bloodtalon delle isole al largo della nostra costa.\n\nTra loro c'è una raptor, la matriarca dei Bloodtalon, particolarmente feroce: ha ucciso molti del nostro villaggio ed è diventata troppo pericolosa per lasciarla ai nostri confini. Se riesci ad abbatterla, torna con le sue uova, così potremo crescere i piccoli come alleati invece che come nemici.", "I Bloodtalon sono noti per la loro astuzia e la loro rapidità, e diventano ottimi compagni se allevati dall'uovo fino all'età adulta.\n\nPurtroppo i raptor adulti sono molto difficili da addestrare, e ho provato a catturare la matriarca più di una volta. Ma ultimamente era diventata troppo pericolosa.\n\nSpero comunque di preservarne l'eredità allevando i suoi piccoli come compagni qui a Sen'jin.", "Grazie, {name}. Sono felice che potremo preservare la sua stirpe e crescere i piccoli come nostri alleati. Hai reso un grande servizio alla nostra tribù.", 0x04cfeed5, 0xc4b71826, 0xb9b4e0b5, 0xa423bd09, 0x25bba0d6, "....." },
  [97225] = { "Idoli loa dimenticati", "Raccogli $N1 Forgotten Loa Idol sulle ⟦Echo Isles=Isole dell'Eco⟧. Portali al maestro Gadrin, al ⟦Sen'jin Village=Villaggio di Sen'jin⟧.", "Quando fuggimmo dalle isole dove ora vivono Zalazane e i suoi simili, lasciammo indietro molti idoli preziosi che ci aiutano a entrare in comunione con gli spiriti che veneriamo: i nostri loa. Sono di grande importanza per la nostra tribù.\n\nI seguaci di Zalazane non mostrano alcuna riverenza per i nostri loa e hanno sparpagliato questi idoli per la più grande delle isole.\n\nÈ un affronto che non passerà inosservato se non riusciremo a raccogliere questi idoli, e offendere un loa è una faccenda grave.\n\nVa', trova quanti più idoli loa puoi e riportameli.", "Hai trovato i nostri idoli loa, {name}? Dobbiamo riprendere presto i nostri rituali.", "Oggi hai compiuto una grande impresa per la nostra tribù.\n\nA differenza di altre tribù, il nostro legame con i loa è fatto di riverenza e rispetto, e dobbiamo loro molto.\n\nNon vorrei che i ⟦Darkspear=Lanciascura⟧ perdessero il loro favore.", 0x3a6e02f8, 0xd654e4c4, 0x689f1998, 0x682f9535, 0x0b095262, "....." },
  [97234] = { "Sala di lettura", "Porta il materiale di lettura impacchettato alla Biblioteca di ⟦Stormwind=Roccavento⟧.", "Sei qui per discutere i significati più profondi delle nostre celebri leggende? No?\n\nBe', quando avrai finito di dare un'occhiata, puoi portare questo alla biblioteca per me? Stiamo scambiando alcune delle nostre opere meno popolari con scritti più moderni. Ho una lista di tomi che il bibliotecario, ne sono certo, potrà procurarci nell'ambito del nostro accordo attuale.\n\nSe ci aiuti, i rinfreschi del club li offriamo noi.", nil, nil, 0x3eee958f, 0xfdbaaa05, 0x221f294c, nil, nil, "...mm" },
  [97236] = { "⟦Fang of Githyiss=Zanna di Githyiss⟧", "Consegna la ⟦Fang of Githyiss=Zanna di Githyiss⟧ a qualcuno ad Aldrassil che si interessi allo studio dei ragni.", "Un esemplare fresco di una bestia di queste dimensioni è una bella scoperta. Forse qualcuno ad Aldrassil che si intende dello studio dei ragni sarebbe interessato alla zanna.", nil, "Bene, bene. Quanto adoro le sorprese, {name}.\n\nQuesto esemplare mi aiuterà di certo a proseguire i miei studi.", 0xc0cb6394, 0xe6a4e5ad, 0x9adc9237, nil, 0xd5fbb580, "...m." },
  [97237] = { "Presi dagli scaffali", "Trova tutti i testi da leggere sparsi per la biblioteca, poi torna da Roy Lewells nel parco di Roccavento.", "Ho controllato il nostro inventario e tutti i titoli elencati dal signor Lewells sono al momento disponibili.\n\nDovrai però prenderli dagli scaffali da te. Parte del nostro dovere di bibliotecari è la vigilanza, e per questo tornerò alla supervisione dei registri.\n\nRiportare il materiale a Roy per conto suo non ti renderà responsabile della sua restituzione: come indica la sua nota, fai da corriere ufficiale del club del libro. Sarà il loro circolo a farsi carico di quell'onere.\n\nBuona giornata, {name}.", nil, nil, 0xa2b3432f, 0xa187b795, 0x7efc8438, nil, nil, "...mm" },
  [97242] = { "Il miscuglio di Yelmak", "Prendi alcune talee dai Cattail e dagli Speargrass che crescono lungo i corsi d'acqua nella ⟦Valley of Honor=Valle dell'Onore⟧ e torna da Kor'geld, da Yelmak's Alchemy and Potions.", "Yelmak non vuole che il suo apprendista rompa qualcosa. Be', qualcosa più di quanto abbia già rotto.\n\nMi ha detto che il giovane miscelatore in addestramento ha troppo orgoglio per chiedere aiuto quando ne ha davvero bisogno. Yelmak vuole fargli assaggiare una certa ricetta fatta in casa.\n\nRaccogli un misto di talee di tifa e di erba lancia dalle piante che crescono attorno all'acqua nella ⟦Valley of Honor=Valle dell'Onore⟧. Ci andrei io, ma se lasciassi la bottega, Whuut capirebbe di sicuro che stiamo assecondando il suo umore.", nil, nil, 0x90c5761e, 0xc53ac54f, 0xb4681896, nil, nil, "...mm" },
  [97243] = { "Il richiamo del fuoco", "Porta la Torch of Dormant Flame a Olariaan Swiftburn allo Shrine of Flames, nei Gustberry Lowlands.", "Anche se siamo nel regno di Skywall, questo resta il piano elementale. Gli spiriti di tutti e quattro gli elementi ci parlano, se ci degniamo di ascoltare. Uno di noi Windshaper è in particolare sintonia con l'elemento del fuoco: uno shen'dorei di nome Olariaan Swiftburn.\n\nPortagli questo allo Shrine of Flames, nei Gustberry Lowlands. Lo troverai nascosto lungo il bordo dell'isola, a ovest di Valanaar.", "Sì, {name}? Che cos'hai lì?", "Dunque hai portato la torcia. Sì, giovane {class}, posso insegnarti a rispondere al richiamo del fuoco. Non sarà facile, ma niente di ciò che facciamo in questo regno è mai facile.", 0x53f3b76b, 0x10e8fa30, 0xb32aea3b, 0xacd1e0ef, 0x89691ed7, "....." },
  [97244] = { "Il richiamo del fuoco", "Uccidi Skypriest Faladiel nei Gustberry Lowlands e raccogli il ⟦Faladiel's Heart=Cuore di Faladiel⟧.", "C'è uno Skypriest degli Al'Aketh di nome Faladiel. Un tempo era un invocatore della fiamma e un fedele Windshaper. Come tanti Al'Aketh, ha barattato la sua lealtà con il potere, e ora le sue mani sono macchiate del sangue dei suoi ex fratelli e sorelle.\n\nTroverai lo Skypriest Faladiel alla fattoria a nord-est, oltre Valanaar, appena a sud dello Shrine of Akir. Uccidi il traditore. Portami il suo cuore. È un compito macabro, ma serve per il rituale che dobbiamo compiere.", "Il cuore di un traditore è un reagente potente. Le fiamme accetteranno avidamente un'offerta simile e arderanno più intense mentre lo consumano.", "I Windshaper non dimenticano, e il sangue si paga sempre con il sangue. Mi compiace che tu sia riuscit<o/a> a consegnare a quel traditore quest'ultimo, doloroso promemoria del nostro credo.\n\nTuttavia, questo cuore non sarà l'unica cosa ad alimentare le fiamme oggi. C'è un altro compito da svolgere.", 0x53f3b76b, 0x7c8f63a5, 0x8ff65707, 0x6c645a00, 0x1c368781, "....." },
  [97245] = { "Il richiamo del fuoco", "Trova la dimora di Kuramaa negli Shen'dar Highlands e sconfiggi lo spirito in combattimento. Quando avrai vinto, porta la ⟦Kuramaa's Mask=Maschera di Kuramaa⟧ a Olariaan Swiftburn nei Gustberry Lowlands.", "Gli abitanti degli Shen'dar Highlands parlano di un antico spirito della foresta chiamato Kuramaa. Dicono che viva dentro un ceppo contorto in cima a una collina, vicino all'Anchor Pylon degli altipiani.\n\nVa' sugli altipiani e trova quel ceppo. Batti il pugno sulla corteccia e Kuramaa apparirà. Sconfiggi lo spirito in combattimento e portami la sua maschera di legno.\n\nMa sta' attent<o/a>: questa entità sarà straordinariamente resistente a gran parte della tua magia. Solo il tocco della fiamma potrà abbattere lo spirito.", "Lo spirito di Kuramaa è eterno, e si manifesterà di nuovo quando ce ne sarà bisogno. La sua maschera è una fonte di grande potere e si rivelerà preziosissima per il rituale che dobbiamo compiere.", "Ora abbiamo ciò che ci serve. Accenderemo la fiamma eterna e comunicheremo con gli spiriti del fuoco.", 0x53f3b76b, 0xf10b3312, 0x5b054c6d, 0xf9b94402, 0xe1d99925, "....." },
  [97246] = { "Un pasto invitante", "Va' al Borstan's Firepit e digli che Thatog vuole che sia tu a consegnare personalmente il pranzo di Migi.", "Mio figlio, Migi, se ne va sempre a giocare con i suoi amici tutto il giorno. Gli dico di passare a prendere il pranzo da Borstan, ma so che non lo fa quasi mai, perché torna a casa affamato. Questi ragazzi pensano che i loro giochi siano più importanti del loro stesso corpo!\n\nTi prego, fermati al Borstan's Firepit e digli che sei lì per consegnare il pranzo di Migi. Quasi certamente troverai Migi dietro Grommash Hold con il resto dei suoi amici.\n\nI miei doveri mi trattengono qui durante il giorno e non posso controllare ogni suo pasto.", nil, "Certo. I genitori di Migi e io abbiamo un accordo per dare a Migi un pranzo al sacco ogni giorno, ma posso assicurarmi che il ragazzo mangi solo se viene davvero a prenderlo.\n\nA volte salta il ritiro del pasto più volte alla settimana, e mi chiedo dove trovi l'energia per restare fuori a giocare.", 0xa80c265e, 0x658ca813, 0x194a00ed, nil, 0x6256c34b, "...m." },
  [97249] = { "Il cibo preferito", "Porta il ⟦Migi's Lunch=Pranzo di Migi⟧ a Migi, dietro Grommash Hold.", "Ora che so che i suoi genitori si preoccupano di quanto si riempia davvero la pancia, mi è venuta un'idea.\n\nMi hanno fatto promettere di non preparare lo stesso pasto tutti i giorni, così Migi prende gusto a più di una cosa. Eppure, ogni volta che l'affumicatoio è pieno e facciamo i panini con pancetta di maiale glassata, lui si presenta sempre a pranzo. Abbiamo cominciato a sbriciolare i pezzetti croccanti di glassa avanzati come guarnizione: una cosa che possiamo aggiungere ogni giorno.\n\nPortagli questo. Magari comincerà a presentarsi presto e a portare gli amici!", "Credo che questa la possiamo vincere...", "Borstan's Meats? È per uno di noi?\n\nOh!\n\nWow... che profumino! Gnam.\n\nGrazie per avermi portato il pranzo. Quando io e i miei amici facciamo la strada per Grommash Hold, capisco già solo dall'odore cosa servirà Borstan ogni giorno. Questo sa del mio preferito, quello glassato! Però è diverso. Mi piacciono le briciole dal sapore forte.\n\nSe sarà così buono tutti i giorni, credo che dovremo interrompere il gioco per pranzare insieme!", 0xd08fbe54, 0x1d99228e, 0x407189ff, 0x603e2035, 0x404a4402, "....." },
  [97250] = { "Accusati a torto, puniti a ragione", "Uccidi i soldati dell'⟦Alliance=Alleanza⟧ che sconfinano nelle ⟦Barrens=Savane⟧ al confine con ⟦Dustwallow Marsh=Acquemorte⟧, poi torna dal grunt Logmar a Camp Taurajo.", "<Viaggiatore/Viaggiatrice>, hai intenzione di dirigerti verso ⟦Dustwallow Marsh=Acquemorte⟧? Ho sentito mormorare che alcuni soldati umani si sono attestati al suo confine e stanno abbattendo i segnali lasciati dai nostri ricognitori tauren.\n\nSi dice che una taverna molto frequentata sia stata rasa al suolo dalle fiamme e, come è tipico dell'⟦Alliance=Alleanza⟧, ne hanno subito dato la colpa all'⟦Horde=Orda⟧! Non posso sapere se le loro accuse abbiano un fondo di verità, ma la loro incursione sulla NOSTRA terra non deve restare impunita.\n\nPrima uccidi, poi indaga!", nil, "Allora le voci erano vere! Me lo aspettavo: le tensioni lungo la costa orientale crescono da tempo. Sapevo che era solo questione di tempo prima che il conflitto si insinuasse nel nostro territorio.\n\nTuttavia, dubito che abbiamo avuto un ruolo nella distruzione della taverna. Troppi civili dell'⟦Horde=Orda⟧ dipendono da quella via per i commerci e i viaggi. Forse potresti indagare più a fondo, se trovi il tempo.\n\nIn ogni caso, l'impresa di oggi è una vittoria per l'⟦Horde=Orda⟧ e un severo monito per l'⟦Alliance=Alleanza⟧!", 0xe1de8387, 0x62527451, 0x121cc5dd, nil, 0xe0593283, "...m." },
  [97253] = { "Pezzi e componenti", "Raccogli $N1 Handfuls of Complicated Parts nell'accampamento pirata superiore a sud di ⟦Ratchet=Porto Paranco⟧, poi torna da ⟦Wrenix the Wretched=Wrenix il Miserabile⟧ a ⟦Ratchet=Porto Paranco⟧.", "Ehi, hai un secondo?\n\nAllora, a quanto pare nessuno di quelli che ho mandato a sistemare il recente problema dei pirati è tornato vivo. Dopo cinque o sei tentativi ho pensato: «E se invece mandassi una macchina?» Salta fuori che le scimitarre, all'occorrenza, fanno anche da cacciavite, e prima che potessi richiamarla a casa era già a pezzi, sparsa per tutto il loro accampamento!\n\nRivoglio quei pezzi, e visto che è una missioncina di recupero veloce, scommetto che le tue probabilità di sopravvivere sono MOLTO più alte di quelle degli altri. Che ne dici?", "Non una parola di più finché le tue tasche non tintinnano di metallo!", "Uaaaah! Bel colpo, amico! Mi hai risparmiato un'altra delle insopportabili prediche di Gagsprocket sul costo del metallo. E soprattutto posso buttarmi subito a costruire il mio prossimo prototipo.\n\nEhm, non avevo previsto una ricompensa... Ti piacciono le scatole?", 0xc374d63c, 0xdd7fd206, 0xd685419d, 0xedc33a12, 0x0ab437e0, "....." },
  [97257] = { "Il richiamo del fuoco", "Aspetta che Olariaan inizi il rituale al Brazier of Offering e segui le sue istruzioni.\n\nDevi portare la Fiamma Eterna a Valanaar prima che scada il tempo.", "Ora eseguiremo il rituale.\n\nMetterò i materiali sull'altare e richiamerò gli spiriti della fiamma. Se l'offerta sarà accettata, appariranno e accenderanno la Fiamma Eterna. Allora tu terrai avanti la torcia e catturerai la fiamma.\n\nPorta la torcia accesa a Valanaar e mettila nel Brazier of Eternal Flames. Devi farlo in fretta, perché le fiamme dei Firelands si dissipano rapidamente qui a Skywall.", "Hai fatto bene ad arrivare fin qui. Fai onore ai Windshaper, {name}.", "È fatta. La Fiamma Eterna arde di nuovo.\n\nLa tua prova è completa. Sono lieto di consegnarti il tuo ⟦Fire Totem=Totem del Fuoco⟧. Usa bene questo simbolo di potere nei tuoi viaggi, {name}.\n\nRicorda solo che il potere del piano elementale serve chi lo rispetta e consuma chi non lo fa. Questa è la nostra via.", 0x53f3b76b, 0x0208cd7e, 0x4a530335, 0x6aa6ef08, 0xaed39338, "....." },
  [97263] = { "Il tuo pacco è arrivato", "Consegna il pacco smarrito di Eldrun.", "<Accanto alla cassetta delle lettere sono stati lasciati diversi pacchi smarriti. Noti che uno di essi va consegnato dal ⟦Aerie Peak=Picco dell'Aquila⟧ a ⟦Ironforge=Forgiardente⟧, a Eldrun Stormbreaker. È contrassegnato come «urgente».>", "Cos'è quello che hai lì?", "Cosa! Vado ogni giorno alla cassetta delle lettere vicino alla banca a cercare questo pacco! Questa città deve rivedere la sua pianta. Non è facile orientarsi come al ⟦Aerie Peak=Picco dell'Aquila⟧!\n\nVediamo cos'ho qui... attrezzi per intagliare totem... un'ascia di riserva... una specie di congegno goblin? Questo non l'ho ordinato! Ah, lo rispedirò indietro.\n\nEhm, cioè... volevo dire... grazie per avermi portato tutta questa roba. Ecco un pensierino per il disturbo.", 0xb90615cc, 0x0f13a33f, 0xc3642e31, 0xdcbf39a7, 0xa4d81308, "....." },
  [97265] = { "Odio per i Furiatorva", "Sconfiggi satiri Furiatorva di vario tipo a Sargeron, a ⟦Desolace=Desolanda⟧, poi torna da Aka'rai a ⟦Shadowprey Village=Predombra⟧.", "Hai mai fatto un patto con un satiro, mon?\n\nIo sì. Come potevo resistere? La promessa del potere, una conoscenza che supera di gran lunga quella di qualsiasi tomo comune... e il tutto insieme a un servitore zelante e carismatico. Cosa potevo chiedere di più?\n\nBah, certo che non avrebbero mai piegato il ginocchio davanti a un mortale. Ho contrattato quando non avevo niente, e mi hanno gettato via lasciandomi con ancora meno.\n\nOra voglio vendetta. Vendetta contro i Furiatorva. Fai irruzione nel loro accampamento a nord-est! Macchia la terra con il loro sangue immondo.", nil, nil, 0x80d3ee17, 0x24ba3490, 0x9c7d33bf, nil, nil, "...mm" },
  [97275] = { "Tanta fretta, Whuut?", "Dai la ⟦Yelmak's Potion=Pozione di Yelmak⟧ a Whuut.", "Whuut è un prodigio. Questo è vero. Ma non ha ancora l'esperienza, la saggezza e le ore passate a rimestare per saper rispettare i processi alchemici.\n\nSta esaurendo tutti i reagenti più rari ed esotici che abbiamo senza fermarsi a esercitare e affinare le sue abilità di base.\n\nDagli questa pozione che ho preparato con un rapido metodo da tonico. Ripenserà a tutto ciò che sta facendo quando capirà che i rimedi locali e un tocco attento sono la prima vera maestria.", nil, nil, 0xdbca40f0, 0xade06c15, 0xe2d2b0c3, nil, nil, "...mm" },
  [97277] = { "Grund e Gozwin", "Trova l'accampamento di Grund e Gozwin sulle colline a nord-ovest. Recupera il ⟦Gozwin's Mechanic's Log=Registro del Meccanico di Gozwin⟧ e uccidi lo Snow Leopard Prowler.", "Oi, ero girato a preparare l'arrosto di cinghiale quando ho sentito il mio amico Gozwin urlare per salvarsi la pelle!\n\nZanne feroci e una macchia confusa, è tutto quel che ho visto quando mi sono voltato. Che zampe enormi! Un leopardo delle nevi si stava trascinando via la sua preda gnomica. Ho afferrato il fucile e ho sparato sopra la bestia. L'ha mollato ed è scappato via di corsa.\n\nPer fortuna non aveva fatto altro che lasciare al vecchio Goz qualche graffio profondo.\n\nTorna all'accampamento sulle colline a nord-ovest e recupera il diario da meccanico di Gozwin. E se vedi quel leopardo delle nevi, ammazza pure lui!", "Il povero Goz si preoccupa più del suo camminatore meccanico che di sé stesso. Dice che se qualcuno mette le mani su quel diario da meccanico, è fritto. Ah! Ecco perché gli ho detto che il lavoro doveva lasciarlo a casa!", "Già, non mi sorprende sapere che quel leopardo delle nevi si stava pappando il cinghiale che stavamo preparando per l'arrosto!\n\nGoz avrà un pensiero in meno ora che gli hai riportato il suo diario. Magari adesso potrà concentrare tutte le energie per rimettersi in piedi.\n\nGrazie, {name}. Prendi un pensierino come segno della mia gratitudine, per aver fatto la scarpinata e per aver protetto le colline.", 0x13ae186f, 0xe97684ed, 0x403ef042, 0x3dbaa3c1, 0xab467190, "....." },
  [97279] = { "Armi smarrite", "Raccogli $N1 Abandoned Training Weapon, poi torna da ⟦Kzan Thornslash=Kzan Sfregiaspine⟧ nell'Antro del Tirocinio.", "Con l'afflusso di nuove reclute come te, è stato difficile tenerci riforniti di armi. Il nostro fabbro d'armi, Kzan, è a corto di armi da addestramento e vorrei vedere che capacità possiedi, per farmi un'idea del materiale con cui devo lavorare. Per tua fortuna, ho una soluzione per entrambe le cose.\n\nMentre sei là fuori a farti le ossa sui cinghiali, recupera sei armi da addestramento abbandonate. Le nostre reclute fallite le hanno lasciate a terra. Fatto questo, riportale al nostro fabbro d'armi Kzan, dietro di me nell'Antro del Tirocinio.", "Throm'ka, {class}. Gorak mi ha detto di aspettarti. È bello vederti <tutto/tutta> <intero/intera>!\n\nSei <riuscito/riuscita> a raccogliere le armi da addestramento che ti ho chiesto?", "Grazie per aver riportato queste armi, {name}. Mi metterò al lavoro per ripararle per la prossima ondata di reclute.", 0x85cc0347, 0x8f4e8fc9, 0x4b72157d, 0xe3abc6ea, 0x21e3c142, "....." },
  [97281] = { "Una tempesta che cova", "Porta il Dull Stormy Orb a Rezlak, vicino alla ⟦Drygulch Ravine=Gola di Fossosecco⟧.", "<Davanti a te c'è uno strano globo dalla superficie opaca. Quando lo raccogli, una debole corrente elettrica sembra vibrare al suo interno. Osservandolo più da vicino, pare che una nebbia scura vi turbini dentro, e di tanto in tanto si scorge una piccola scintilla elettrica.\n\nÈ chiaro che l'arpia lo usava per qualche scopo. Forse Rezlak sarebbe interessato a questo oggetto?>", nil, "Uh, dove hai trovato un aggeggio forte come questo? Sai, mi ricorda l'altra cosa che il mio capo ⟦Gazlowe=Sparachiodi⟧ mi diceva sempre...", 0x1d3d3e08, 0xbc513c0b, 0x8130886a, nil, 0x703847de, "...m." },
  [97282] = { "Potenziale tempestoso", "Porta $N1 Charged Thunder Lizard Organ a Rezlak, vicino alla ⟦Drygulch Ravine=Gola di Fossosecco⟧.", "«Rezlack, quando un'occasione bussa alla porta, assicurati di essere pronto a coglierla». È un'altra perla che mi ha insegnato ⟦Gazlowe=Sparachiodi⟧, ed è proprio quello che intendo fare.\n\nQuesto globo non sembra danneggiato, ha solo l'aria di essere scarico, ma ho in mente di sovraccaricarlo per riportarlo alla piena potenza!\n\nC'è un mucchio di sauri del tuono in una gola a ovest di qui. Hanno organi che trattengono una forte carica elettrica, perfetti per questo.\n\nVa' a prenderne un po' e portameli!", "Forse ti sorprenderà che, con un nome come sauro del tuono, sparino fulmini invece di ruggire come il tuono.\n\nE invece lo fanno. Sparano fulmini, intendo.\n\nFidati, è una lezione che, se ti va bene, impari una volta sola.", "Ehi, grazie, amico! Mi hai dato davvero una grossa mano qui, e te ne sono grato.\n\nSperiamo di riuscire a ricaricarlo per bene con questi organi. Scommetto che farà pensare due volte quelle arpie buone a nulla prima di attaccare di nuovo la mia carovana. Spero proprio che funzioni.\n\nIn ogni caso, tu hai fatto la tua parte dell'accordo. Prendi questo per il disturbo.", 0xcc6ed58f, 0x1994e522, 0x12b14931, 0xaea78271, 0xe9dc28ef, "....." },
  [97284] = { "La vendetta di Vahlarriel", "Uccidi gli orchi delle ⟦Burning Blade=Lame Ardenti⟧ alla ⟦Thunder Axe Fortress=Fortezza Ascia del Tuono⟧, a ⟦Desolace=Desolanda⟧, poi torna da ⟦Vahlarriel Demonslayer=Vahlarriel Stroncademoni⟧ al ⟦Nijel's Point=Presidio di Nijel⟧.", "Se Malem è ancora viva, sospetto che gli orchi delle ⟦Burning Blade=Lame Ardenti⟧ si aspettino che presto qualcuno venga a cercarla. Saranno di certo pronti a combattere.\n\nPreferirei che tenessi un profilo basso e restassi alla larga da loro, ma è molto più probabile che cerchino di affrontarti, lama contro ⟦Burning Blade=Lame Ardenti⟧, a ogni occasione.\n\nQuindi, che ne dici di tenere il conto fin dall'inizio? Uccidine quanti più puoi, e ne varrà la pena per te.", nil, nil, 0x8067ec59, 0xf8a6125b, 0x9c85e944, nil, nil, "...mm" },
  [97286] = { "Accesso alle ricerche", nil, nil, nil, "Le tue azioni dimostrano che rispetti la conoscenza. La biblioteca è aperta per i tuoi studi.", 0xd0907e8d, nil, nil, nil, 0x0972665c, ".mmm." },
  [97287] = { "Trattative astute", "Parla con l'immagine dell'arcimaga Modera, vicino a Dalaran.", "Hai fatto bene a infiltrarti nella città dei maghi, ma credo sia giunto il momento di essere più... negoziali.\n\nPer quanto mi costi ammetterlo, non c'è altro luogo su Azeroth con una conoscenza così vasta dell'arcano. Il mio brillante lavoro impallidisce ancora di fronte all'antica saggezza che il Kirin Tor ha accumulato negli anni. Credo sia ora che ci venga concesso l'accesso a questo ordine esclusivo, non trovi?\n\nPrendi il granello che hai ottenuto. Daranno di sicuro qualsiasi cosa per riaverlo. Qualsiasi cosa.", nil, nil, 0xe4acb80b, 0x93700c3f, 0xb6c29c5f, nil, nil, "...mm" },
  [97288] = { "Tormento senza fine", "Consegna la ⟦Abominable Head=Testa Abominevole⟧ al maestro speziale Faranell, a ⟦Undercity=Sepulcra⟧.", "<Mentre la creatura cade, la testa le rotola via. Sembra che sia stata riattaccata più volte e che a ogni nuovo attacco la giunzione si indebolisca.\n\nQualcuno a ⟦Undercity=Sepulcra⟧ saprà di più su questo singolare abominio.>", "Che cos'abbiamo qui?", "Oho! Credo di conoscere questa testa. Uno scherzo crudele della nostra Dama Oscura. E pure delizioso.\n\nCredo di sapere come usarla.", 0x88dcf75e, 0x5d3272d3, 0x045ff381, 0x2b2c91f6, 0x3d028316, "....." },
  [97289] = { "Tormento senza fine", "Porta la ⟦Head of the Baron=Testa del Barone⟧ al corpo di Othmar, a ⟦Undercity=Sepulcra⟧.", "Teste di abominio ne fabbrichiamo di continuo, ma questa è speciale. Un tempo apparteneva a un gran maresciallo dell'⟦Alliance=Alleanza⟧. Uno particolarmente sgradevole. Othmar, credo si chiamasse. La Dama Oscura ebbe il piacere di sbarazzarsene di persona.\n\nOh, i segreti che potrebbe raccontare, se potesse parlare. E può! Basta riattaccarla a un ospite adatto.\n\nVa', mettila accanto al corpo disponibile nella stanza accanto. Ma non attaccarla. Non ancora.", "<L'abominio resta senza vita, privo di una testa che lo controlli.>", "<Il corpo si contrae tornando in vita, in preda al panico mentre rivive i suoi ultimi istanti.>\n\nTu...", 0x88dcf75e, 0x8392a5dc, 0x21af4dd7, 0x09afdccf, 0xf5efb3f9, "....." },
  [97290] = { "Tormento senza fine", "Riferisci le tue scoperte al maestro speziale Faranell, a ⟦Undercity=Sepulcra⟧.", "Tu... abominio...\n\nPerché dovrei... aiutarti...\n\nVattene...", nil, "Non collabora, eh? Eccellente. Adoro le sfide.", 0x88dcf75e, 0x76cbafb3, 0x0d26ec99, nil, 0xdfbc27f5, "...m." },
  [97291] = { "Tormento senza fine", "Raccogli un ⟦Toxic Skullcap=Cappello Tossico⟧ da Tawny Grisette nel ⟦Trade Quarter=Quartiere del Commercio⟧, dell'⟦Blisterweed=Erbavescica⟧ vicino all'istruttore di Erbalismo e dell'⟦Essence of Agony=Essenza d'Agonia⟧ dal venditore di veleni nel ⟦Rogues' Quarter=Quartiere dei Ladri⟧, per il maestro speziale Faranell a ⟦Undercity=Sepulcra⟧.", "Ora che la testa è riattaccata, non resta che piegarla alla volontà della Dama Oscura. Non dovrebbe essere un problema. Dopo tutte le botte che ha preso, a quella bestia è rimasto ben poco cervello.\n\nDobbiamo solo motivarla.\n\nPortami un ⟦Toxic Skullcap=Cappello Tossico⟧ dalla signorina Grisette, nel ⟦Trade Quarter=Quartiere del Commercio⟧. Ah, e un po' di ⟦Blisterweed=Erbavescica⟧ dai nostri istruttori di Erbalismo, gli Alliestar. Prendine pure, sono in debito con me. E infine un po' di ⟦Essence of Agony=Essenza d'Agonia⟧. Andrà bene un qualsiasi venditore di veleni.\n\nAbbiamo una pozione da preparare!", "Sarà così bello riavere all'ovile la nostra pecorella smarrita, non trovi?", "Andranno benissimo. Vedremo quanta spavalderia conserverà il nostro illustre ospite dopo aver assaggiato il mio capolavoro.", 0x88dcf75e, 0x3c831878, 0x10e94e21, 0xe35d5b4a, 0x7ba6274b, "....." },
  [97292] = { "Tormento senza fine", "Inietta il ⟦Hissing Serum=Siero Sibilante⟧ nel sistema sopra il corpo di Othmar, per il maestro speziale Faranell.", "Ho preparato un delizioso siero che il nostro nuovo ospite troverà di certo molto... stimolante.\n\nPrendi. Versalo nel congegno che gocciola sopra di lui. Vediamo se riusciamo a fargli capire che servire con lealtà è nel suo interesse.\n\nE cerca di non farlo cadere. Non posso permettermi un nuovo assistente.", "Per i crimini di Othmar contro la Dama Oscura, metterlo sotto quell'esemplare gocciolante è il minimo che si meriti.\n\nE poi è divertente...", "Eccellente. Lasceremo che la sua carne sobbolla per un po'. Diamogli il tempo di abituarsi alla sua nuova casa.\n\nPer ora quel miserabile non mi serve più, ma lo terremo d'occhio. Ho molti progetti per il futuro di Othmar.", 0x88dcf75e, 0xcad79e1e, 0xfef7f8a7, 0x92d9ddce, 0x51def099, "....." },
  [97326] = { "Dai sassi ai sedili", "Riporta $N1 Smooth Boulder a Thra, dietro Grommash Hold.", "Ehi! Tu hai tempo per aiutarci! Lo so che ce l'hai, l'ho capito da come sorridevi guardando il gioco che stiamo facendo.\n\nQuesto posto dietro Grommash Hold è bello perché è abbastanza sgombro per sistemare le nostre pedine. Ma la cosa brutta è che non abbiamo abbastanza sassi per fare sedie o tavoli.\n\nTu sei grande e forte... pensi di poter portare qui qualche sasso di media grandezza, abbastanza liscio da sederci sopra se ci serve una pausa?", "È bello non dover sempre stare seduti nella terra!", "Ma come fai a reggere tutti quei massi!\n\nSono perfetti. Quasi tutti hanno pure un bel lato piatto. Ora che li hai portati fin qui, possiamo spingerli nella terra proprio dove li vogliamo.\n\nGrazie, {name}!", 0xf790b060, 0xc71bf5e0, 0x831d0833, 0x1382164d, 0xc29549c2, "....." },
  [97328] = { "Qualcosa di valore", "Recupera $N1 Stolen Shipment dalle ⟦Ruins of Zul'Kunda=Rovine di Zul'Kunda⟧, nella Valle di Rovotorto, e porta il carico a qualcuno alla ⟦Booty Bay=Baia del Bottino⟧.", "<Frugando tra i rottami lasciati da un terribile schianto di zeppelin proprio qui sopra, trovi le tracce di un grosso carico di rifornimenti, saccheggiato da tempo di tutto ciò che aveva valore. Persino le etichette di spedizione sono state strappate e fatte a brandelli: su una si leggono a malapena le parole \"⟦Booty Bay=Baia del Bottino⟧\".\n\nInnumerevoli impronte a due dita e diverse chiazze di terra smossa portano tutte verso delle rovine a nord-ovest.>", nil, nil, 0xd56cd924, 0x19d4694d, 0xa7fe74f8, nil, nil, "...mm" },
  [97329] = { "Dov'è la chiave?", "Porta a Zimmix Sputterspark la ⟦Primitive Key=Chiave Primitiva⟧ presa ai troll delle Rovine di Zul'Kunda, nella Valle di Rovotorto.", "Tu! Sì, tu! Vieni qui, abbassa la voce!\n\nHo fatto un pasticcio enorme. Ero riuscito a strappare un affarone per usare la torre degli zeppelin della ⟦Booty Bay=Baia del Bottino⟧ per le consegne rapide, e proprio sulla prima rotta ho visto un uccello gigante... ehm, mi hanno ABBATTUTO, proprio qui a est!\n\nSono sopravvissuto allo schianto, purtroppo, ma prima ancora di svegliarmi mi stavano già trascinando per le orecchie! Ora sono circondato da troll assetati di sangue e chiuso in una gabbia!\n\nSenti, mi serve solo la chiave, d'accordo? Posso scappare da solo.", nil, nil, 0x4cd8cc0a, 0x11d8de27, 0x2fef21bb, nil, nil, "...mm" },
  [97331] = { "La grande fuga di Zimmix", "Scorta Zimmix Sputterspark lontano dalle ⟦Ruins of Zul'Kunda=Rovine di Zul'Kunda⟧, poi racconta al capitano del porto Malattracco, alla ⟦Booty Bay=Baia del Bottino⟧, che il salvataggio è riuscito.", "Aspetta, aspetta, non andartene ancora!\n\nLo so che ho detto che mi serviva solo la chiave, ma... be', mi hanno preso una volta, potrebbero rifarlo, no? Sono solo un goblin, e qui intorno ci sono centinaia di troll!\n\nNe hai già fatti fuori abbastanza per prendere questa chiave, quindi dovrebbe essere facile fare la guardia mentre ce la filiamo da qui, eh?", nil, nil, 0x27ec33fb, 0x6aebab8a, 0xad346a39, nil, nil, "...mm" },
  [97420] = { "Riduci, riusa, riconcilia", "Procurati $N1 Drums of Crude Oil dagli impianti della S.P.R. & Co. al ⟦Lake Nazferiti=Lago Nazferiti⟧, poi torna da ⟦Knaz Blunderflame=Knaz Fiammacurva⟧ nella Valle di Rovotorto.", "Ho un favore da chiedere a qualcuno, e tu hai l'aria di uno che aiuta!\n\nVedi questa bellezza? Non è una meraviglia? È il mio nuovo bolide da corsa, progettato e costruito tutto da me, perché QUALCUNO non ha voluto aiutarmi. Voglio portarlo alle gare di ⟦Thousand Needles=Millepicchi⟧, ma gli serve una spintarella in più.\n\nOra, io sono troppo bello per essere un goblin, e so bene che non c'è da fidarsi della loro tecnologia, ma so che la S.P.R. & Co. ha trovato oro liquido laggiù al lago. Sono sicuro che non gli dispiacerà se tu, ehm, ne prendessi un po' in prestito. Non se ne accorgeranno nemmeno!", nil, nil, 0x4056755c, 0xc361c56c, 0x4d212a67, nil, nil, "...mm" },
  [97485] = { "Le tradizioni del Picco", "Compra un ⟦Bundle of Herbs=Mazzo di Erbe⟧ da Nida, che vende erbe, un Bundle of Cedar Twigs da Nata, che vende materiali per incantamento, del ⟦Sinew Thread=Filo di Tendine⟧ da Mahu, che vende materiali per conciatura, e una ⟦Ceremonial Flint and Tinder=Pietra Focaia ed Esca Cerimoniali⟧ da Naal, che vende materiali per cucina.\n\nUnisci gli oggetti e spargi l'incenso dall'Hunter's Rise.", "Che An'she ti benedica, amico.\n\nNoi tauren abbiamo la tradizione di spargere incenso ai venti, e speravo che ti interessasse onorarla.\n\nDovrai preparare l'incenso comprando le erbe da Nida, il cedro da Nata, il filo di tendine da Mahu sul terrazzo di mezzo, e la pietra focaia ed esca cerimoniale da Naal sul terrazzo più alto. Quando avrai questi oggetti, uniscili e spargili dalla scogliera rivolta a sud dell'Hunter's Rise.\n\nTroverai una stuoia e dell'incenso nel luogo della cerimonia.", "Ci sono molte occasioni in cui si può scegliere di spargere incenso ai venti. Potresti chiedere alla Madre Terra di vegliare su qualcuno, benedire una caccia, celebrare un'occasione o perfino cercare la guida dei nostri antenati.\n\nOppure potrebbe essere tutt'altro.\n\nAnche se il gesto si compie con reverenza, non è un rito strettamente cerimoniale. Di solito si seguono alcuni passi tradizionali, ma molte tribù hanno usanze diverse.", "Hai fatto bene.\n\nTi ringrazio per aver dedicato del tempo a una delle nostre tradizioni più antiche, {race}. Spero che nei tuoi viaggi troverai tante occasioni per cui rendere grazie.\n\nSe mai vorrai ripetere il rito, potrai ricomprare gli ingredienti che ti ho mandato a raccogliere.\n\nVa' con il calore di An'she.", 0x8de39461, 0x5aef4be7, 0xd944b43a, 0xb3960157, 0x1cd730cd, "....." },
  [97538] = { "Pigmenti per i colori", "⟦Tah Winterhoof=Tah Zoccolo Artico⟧, a ⟦Thunder Bluff=Picco del Tuono⟧, vuole $N1 ⟦Mirkweed Pods=Baccelli di Alga Torbida⟧ dal ⟦Mirkfallon Lake=Lago Mirkfallon⟧.", "Salute, amico. Posso chiederti un favore? Ho appena finito il pigmento rosso per i miei colori, e cerco qualcuno con gli zoccoli più giovani dei miei che faccia per me il lungo viaggio fino alle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧.\n\nA metà del passo montano c'è un grande lago rotondo, il ⟦Mirkfallon Lake=Lago Mirkfallon⟧, nelle cui acque cresce una pianta unica. I baccelli di questa pianta, il mirkweed, diventano di un rosso vivo una volta seccati. Raccogli per me i baccelli di questa pianta e ti ricompenserò bene per la fatica.", nil, nil, 0xaa3850ee, 0x98b0df48, 0xd373bd5c, nil, nil, "...mm" },
  [97539] = { "Suture di seta", "Riporta 12 ⟦Surgical Spidersilk=Seta di Ragno Chirurgica⟧ al dottor Gregory Victor a ⟦Hammerfall=Requie del Martello⟧, negli ⟦Arathi Highlands=Altopiani d'Arathi⟧.", "Questo accampamento è lasciato a marcire. I danni dell'assedio restano lì, senza riparazioni, come se l'incuria fosse una regola. Non permetterò lo stesso degrado qui. L'infermeria risponde a me, e intendo tenerla in funzione.\n\nSiamo quasi senza scorte. Mi serve altro materiale, abbastanza da tenere in piedi lavoratori e guardie.\n\nIn caso di necessità, con la seta di ragno ritorta si può fare una sutura da campo molto efficace.\n\n{class}, portamene un po' dai ragni che si aggirano per questi altopiani.", nil, nil, 0xdf5a915e, 0x4b00338c, 0x5c3dc6d2, nil, nil, "...mm" },
  [97558] = { "Pelli per i Reietti", "Porta a Shelene Rhobart $N1 Duskbat Wing Membrane, $N2 Darkhound Hide e $N3 ⟦Vile Fin Murloc Skin=Pelle di Murloc Pinnainfame⟧.", "C'è un aspetto della non morte di cui nessuno parla: cosa succede quando veniamo feriti. Come guarisce la pelle di un non morto?\n\nBe', non guarisce.\n\nLa nostra è una vita maledetta, {name}. Dobbiamo prendere dai vivi per prolungare la nostra esistenza.\n\nQuando subiamo una ferita dobbiamo sostituire la pelle, e di solito questo vuol dire pelli di animali. Visto che spessori diversi si adattano meglio a punti diversi del corpo, la varietà è fondamentale!\n\nPortami le membrane delle ali di un pipistrello del vespro, le pelli di un segugio oscuro e la pelle di un murloc Vile Fin.", "Hai raccolto la pelle che ti ho chiesto? Le nostre scorte si stanno esaurendo.\n\nPuò sembrare strano chiedere pelle di murloc, ma funziona bene per le membrane interne o per superfici come guance e bocca.\n\nAllo stesso modo, le membrane delle ali dei pipistrelli del vespro sono particolarmente adatte alle zone più delicate, come il viso o le dita. Evitano che la pelle sia troppo... spessa.", "Ah, eccellente! Grazie per averle procurate. Ti prometto che saranno usate a dovere.", 0x09dcf31d, 0x19613344, 0x932d29f0, 0x6d509c4e, 0x35944081, "....." },
  [97583] = { "DIMENATI.", "Compra della ⟦Nutritious Slime Sludge=Fanghiglia di Melma Nutriente⟧ e torna dalla melma vivace che hai fatto tua amica. Se sembra stanca, prova di nuovo a ballare con lei per attirare la sua attenzione.", "<La piccola melma sembra felicissima e cerca di imitare i tuoi movimenti mentre balli. Però comincia ad avere l'aria stanca.\n\nLa piccola melma si sposta sopra un po' di poltiglia e la assorbe, e sembra un po' rinvigorita.\n\nPare che tutto questo ballare l'abbia sfinita. Forse qualcuno nei canali di ⟦Undercity=Sepulcra⟧ vende altra di questa poltiglia nutriente?>", nil, nil, 0x196f6916, 0x0ed19c12, 0x943783d3, nil, nil, "...mm" },
  [97891] = { "Corriere di pozioni puntuale", "Porta la ⟦Unstable Potion=Pozione Instabile⟧ al dottor Martin Felben, all'Apothecarium, entro il tempo limite.", "Tu! Presto, devi portare questa pozione oltre il canale di melma, al dottor Martin Felben, all'Apothecarium!\n\nSi conserva per pochissimo tempo, e no, non posso andarci io: se provo a correre, le ginocchia mi scricchiolano e saltano via.\n\nUn altro delizioso effetto collaterale della non morte, a quanto pare.\n\nMa stiamo perdendo tempo! Ecco, prendi e vai!\n\n<Alessandro ti fa cenno di sbrigarti.>", nil, "Ah, meraviglioso! Aspettavo che arrivasse la pozione di Alessandro. Le ultime sei che ha mandato si sono destabilizzate per strada, ma tu sei arrivat<o/a> appena in tempo!\n\nEcco, prendi questo per il disturbo. Per ora è tutto, a meno che tu non abbia altri affari con me.\n\nIn caso contrario, togliti di torno, così posso continuare i miei esperimenti in pace.", 0x5ecd7075, 0x57e062c5, 0x38a757cf, nil, 0xad4dc35c, "...m." },
  [97894] = { "Affari ad Auberdine", "Controlla come sta ⟦Gorbold Steelhand=Gorbold Mandacciaio⟧ ad Auberdine, a ⟦Darkshore=Rivafosca⟧.\n\nBorgus ha parlato di una nave, al molo più a sud del porto di ⟦Stormwind=Roccavento⟧, che può portarti laggiù.", "Piacere di fare la tua conoscenza! Mi chiamo Borgus, della sola e unica famiglia Steelhand. Con uno Steelhand puoi sempre contare su un affare onesto!\n\nQualche settimana fa mio fratello Gorbold si è messo con una bancarella di mercanti ad Auberdine. C'è un sacco di soldi da fare rifornendo le navi, laggiù, credimi! Che fortunello.\n\nDa allora non ho più avuto sue notizie. Ti spiace controllare come sta, se vai da quelle parti?\n\nNel porto c'è una nave nuova che ti porterà dritto laggiù. Va' al molo più a sud: non puoi sbagliare!", nil, "Ti manda il vecchio Borgy? Pensa sempre a me.\n\nUn altro paio di mani qui ci farebbe proprio comodo. Con la recente tragedia gli affari si sono quasi fermati, e credo che tu possa aiutare a rimettere le cose a posto.", 0x05e986b2, 0xc51e34fa, 0x4f88604b, nil, 0xe4fd9705, "...m." },
  [97899] = { "⟦Camping=Campeggio⟧ 101: Alchimia", "Parla con Whuut a Orgrimmar per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Dunque hai scelto di preparare intrugli e pozioni come alchimista. Di sicuro ti tornerà utile nei tuoi viaggi.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Mana Well=Pozzo di Mana⟧ per il tuo accampamento. Costruiscine uno e tutti i guaritori e i lanciatori di incantesimi accorreranno per gustarne un sorso rinfrescante.", nil, nil, 0x32f4ba12, 0xc1f8026d, 0xf6c52c29, nil, nil, "...mm" },
  [97900] = { "⟦Camping=Campeggio⟧ 101: Forgiatura", "Parla con Dwukk a ⟦Razor Hill=Tranciacolle⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Dunque ti sei dat<o/a> alla Forgiatura. Ottima scelta, se vuoi che le tue lame non perdano mai il filo.\n\nMi sa che conosco qualcuno che può aiutarti, insegnandoti a fabbricare una ⟦Sharpening Wheel=Mola per Affilare⟧. Tirane fuori una al tuo accampamento e tutti i guerrieri e i ladri dei dintorni faranno la fila per affilare le loro armi.", nil, nil, 0x16979ea3, 0xc5732bbb, 0x469a706e, nil, nil, "...mm" },
  [97901] = { "⟦Camping=Campeggio⟧ 101: Incantamento", "Parla con Jhag a Orgrimmar per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Gli incantatori rendono migliore ogni cosa e sono sempre i benvenuti in qualsiasi accampamento nelle terre selvagge.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Enchanted Lute=Liuto Incantato⟧ per il tuo accampamento. È importantissimo trovare un po' di svago nei momenti di riposo, e questo pizzico di magia può aiutarti a essere pront<o/a> ad affrontare ogni sorta di sfida quando riprenderai la vecchia strada polverosa.", nil, nil, 0x2e9b8c15, 0xd5fb1529, 0xb4a29ffc, nil, nil, "...mm" },
  [97902] = { "⟦Camping=Campeggio⟧ 101: Ingegneria", "Parla con Mukdrak a ⟦Razor Hill=Tranciacolle⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Gli ingegneri come te sanno inventarsi ogni sorta di congegni, robot e bombe, per divertimento e per profitto.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Reagent Bot=Robot dei Reagenti⟧ per il tuo accampamento. Questo utile automa può aiutarti a restare ben rifornit<o/a>, così tu e i tuoi alleati non resterete mai senza i materiali che servono ad alimentare i vostri incantesimi.", nil, nil, 0x1cb4025b, 0xcf977e31, 0x549b28c0, nil, nil, "...mm" },
  [97903] = { "⟦Camping=Campeggio⟧ 101: ⟦First Aid=Primo Soccorso⟧", "Parla con Rawrk a ⟦Razor Hill=Tranciacolle⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Quindi ti sei dat<o/a> al ⟦First Aid=Primo Soccorso⟧? È un'attività onorevole... e pragmatica per <un/una> {class}.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦First Aid Kit=Kit di Primo Soccorso⟧ per il tuo accampamento. Nella vita d'avventura le ferite sono una realtà, e offrire un po' di cure tanto necessarie al tuo accampamento potrebbe persino salvare delle vite.", nil, "Ecco fatto: ora puoi fabbricare un ⟦First Aid Kit=Kit di Primo Soccorso⟧ tutto tuo. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0x6e7c255b, 0xa11a2e39, 0x32ff3188, nil, 0x3a282524, "...m." },
  [97904] = { "⟦Camping=Campeggio⟧ 101: Pesca", "Parla con ⟦Lau'Tiki=Lau'tiki⟧ vicino al ⟦Sen'jin Village=Villaggio di Sen'jin⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Forse non lo diresti, ma la tua abilità nella Pesca può davvero tornare utile all'accampamento.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una ⟦Fish Bowl=Boccia per Pesci⟧ per il tuo accampamento. Puoi usare questo arredo per portare un po' di gioia a te e ai tuoi compagni d'avventura. Un avventuriero felice è un avventuriero forte, e di sicuro le tue capacità in combattimento lo dimostreranno.", nil, nil, 0xe0c1c700, 0x7cb6468b, 0x1bcf05fd, nil, nil, "...mm" },
  [97905] = { "⟦Camping=Campeggio⟧ 101: Erbalismo", "Parla con Jandi a Orgrimmar per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Mi pare che tu abbia acquisito una certa abilità nell'Erbalismo. Raccogliere fiori non serve solo a perdere tempo, sai. Può essere utile... e redditizio.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una ⟦Incense Candle=Candela d'Incenso⟧ per il tuo accampamento. Il morale alto è fondamentale per tenere in battaglia guaritori e lanciatori di incantesimi, e una ⟦Incense Candle=Candela d'Incenso⟧ può dare una spinta che chi usa la magia apprezzerà di certo.", nil, "Ecco qua, ora tu sai creare una ⟦Incense Candle=Candela d'Incenso⟧ tutta tua. Alla gente non piace tanto che si piantano accampamenti in mezzo al paese, quindi tu devi andare nelle terre selvagge se vuoi provarla.\n\nNessun accampamento è completo senza un fuoco, amico. Te ne serve uno prima di allestire il tuo accampamento. Quasi tutti i cuochi ti insegnano ad accendere un fuoco. Passa da qualcuno che ti istruisce nell'arte culinaria, se le basi ancora non le hai imparate.", 0xd7cde71c, 0xdecd7cd7, 0xe0048777, nil, 0x37424fd5, "...m." },
  [97906] = { "⟦Camping=Campeggio⟧ 101: Conciatura", "Parla con Karolek a Orgrimmar per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Così ora lavori il cuoio. Buon per te, {class}. Mi sa che conosco qualcuno che può insegnarti a fabbricare una tenda che ti terrà al fresco nei giorni caldi e all'asciutto in quelli di pioggia.\n\nCon una buona tenda sopra la testa, avrai tutto il riposo che ti serve per restare in forma durante i tuoi viaggi.", nil, nil, 0x40d05936, 0x78212a11, 0x86e620e9, nil, nil, "...mm" },
  [97907] = { "⟦Camping=Campeggio⟧ 101: Estrazione", "Parla con Krunn a ⟦Razor Hill=Tranciacolle⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "L'Estrazione non sarà il mestiere più affascinante, ma è un lavoro onesto e una bella professione da esplorare.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Lodestone=Magnetite⟧ per il tuo accampamento. Costruiscine una e chiunque voglia menare la spada non vedrà l'ora di radunarsi attorno al tuo fuoco per assorbire quella \"grinta\" in più che può dare alla sua abilità in combattimento.", nil, nil, 0xa8fe12f3, 0x7978666b, 0x8ef0fff6, nil, nil, "...mm" },
  [97908] = { "⟦Camping=Campeggio⟧ 101: Scuoiatura", "Parla con Thuwd a Orgrimmar per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Saper ricavare con abilità pelli e cuoi dalle bestie abbattute è una delle capacità più preziose che un avventuriero possa avere.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una ⟦Camp Chair=Sedia da Campo⟧ per il tuo accampamento. A volte è importante concedersi un po' di riposo, e puoi usare alcune delle pelli che hai raccolto per farti una sedia comoda su cui sederti. Un po' di relax può aiutarti a restare in piena forma e a colpire dove conta la prossima volta che ti ritroverai in una zuffa.", nil, "Ecco fatto: ora puoi fabbricare una ⟦Camp Chair=Sedia da Campo⟧ tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0x14236b38, 0xd889c883, 0x1755b1ba, nil, 0x98c24a76, "...m." },
  [97914] = { "Nuovi orizzonti", "Porta la ⟦Thundris' Letter=Lettera di Thundris⟧ a Baros Alexston, a ⟦Stormwind=Roccavento⟧.\n\nThundris ha parlato di una nave ad Auberdine che può portarti laggiù.", "Auberdine è un luogo modesto, {class}. Non sentirai pronunciare il suo nome tra le fronde di Darnassus. I più ricordano solo ciò che la Separazione ci ha tolto: le fiorenti città di ⟦Ameth'Aran=Ameth'aran⟧, ⟦Bashal'Aran=Bashal'aran⟧ e... Lathar'Lazal.\n\nEppure Auberdine resta nella loro ombra.\n\nVorrei che il nostro lavoro qui fosse riconosciuto. Una nuova nave ci collega al regno di ⟦Stormwind=Roccavento⟧, portando vita e rifornimenti sulle nostre coste. Ti prego di unirti al suo prossimo viaggio e di portare questa lettera a un umano di nome Baros Alexston.\n\nFai conoscere la nostra casa.", "Sento odore di mare su di te, amico!\n\n<Baros ride.>\n\nChe cosa ti porta a ⟦Stormwind=Roccavento⟧?", "<Baros apre la lettera e comincia a leggerla, mentre il sorriso gli svanisce dal volto.>", 0x47bf47e5, 0xe531658d, 0x0d17a10a, 0xccc0bbea, 0x30ab094d, "....." },
  [97915] = { "⟦Camping=Campeggio⟧ 101: Alchimia", "Parla con l'alchimista Mallory nella ⟦Elwynn Forest=Foresta di Elwynn⟧, vicino a ⟦Stormwind=Roccavento⟧, per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Dunque hai scelto di preparare intrugli e pozioni come alchimista. Di sicuro ti tornerà utile nei tuoi viaggi.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Mana Well=Pozzo di Mana⟧ per il tuo accampamento. Costruiscine uno e tutti i guaritori e i lanciatori di incantesimi accorreranno per gustarne un sorso rinfrescante.", nil, nil, 0x32f4ba12, 0x7a5b40ad, 0xf6c52c29, nil, nil, "...mm" },
  [97916] = { "⟦Camping=Campeggio⟧ 101: Forgiatura", "Parla con il fabbro Argus a ⟦Goldshire=Borgodoro⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Dunque ti sei dat<o/a> alla Forgiatura. Ottima scelta, se vuoi che le tue lame non perdano mai il filo.\n\nMi sa che conosco qualcuno che può aiutarti, insegnandoti a fabbricare una ⟦Sharpening Wheel=Mola per Affilare⟧. Tirane fuori una al tuo accampamento e tutti i guerrieri e i ladri dei dintorni faranno la fila per affilare le loro armi.", nil, "Ecco fatto, ora puoi creare una ⟦Sharpening Wheel=Mola per Affilare⟧ tutta tua. Alla maggior parte della gente non piace che si piantino accampamenti in mezzo al paese, quindi dovrai andare nelle terre selvagge se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco. Te ne servirà uno prima di allestire il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, faresti bene a passare da qualcuno che possa istruirti nell'arte culinaria per imparare le basi.", 0x16979ea3, 0xbc0dd4f8, 0x469a706e, nil, 0xe5c38af5, "...m." },
  [97917] = { "⟦Camping=Campeggio⟧ 101: Incantamento", "Parla con Betty Quin a ⟦Stormwind=Roccavento⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Gli incantatori rendono migliore ogni cosa e sono sempre i benvenuti in qualsiasi accampamento nelle terre selvagge.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Enchanted Lute=Liuto Incantato⟧ per il tuo accampamento. È importantissimo trovare un po' di svago nei momenti di riposo, e questo pizzico di magia può aiutarti a essere pront<o/a> ad affrontare ogni sorta di sfida quando riprenderai la vecchia strada polverosa.", nil, nil, 0x2e9b8c15, 0x1d55369b, 0xb4a29ffc, nil, nil, "...mm" },
  [97918] = { "⟦Camping=Campeggio⟧ 101: Ingegneria", "Parla con ⟦Sprite Jumpsprocket=Sprite Giramolla⟧ a ⟦Stormwind=Roccavento⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Gli ingegneri come te sanno inventarsi ogni sorta di congegni, robot e bombe, per divertimento e per profitto.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Reagent Bot=Robot dei Reagenti⟧ per il tuo accampamento. Questo utile automa può aiutarti a restare ben rifornit<o/a>, così tu e i tuoi alleati non resterete mai senza i materiali che servono ad alimentare i vostri incantesimi.", nil, nil, 0x1cb4025b, 0xba6c8a24, 0x549b28c0, nil, nil, "...mm" },
  [97919] = { "⟦Camping=Campeggio⟧ 101: ⟦First Aid=Primo Soccorso⟧", "Parla con Michelle Belle a ⟦Goldshire=Borgodoro⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Quindi ti sei dat<o/a> al ⟦First Aid=Primo Soccorso⟧? È un'attività onorevole... e pragmatica per <un/una> {class}.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦First Aid Kit=Kit di Primo Soccorso⟧ per il tuo accampamento. Nella vita d'avventura le ferite sono una realtà, e offrire un po' di cure tanto necessarie al tuo accampamento potrebbe persino salvare delle vite.", nil, "Ecco fatto: ora puoi fabbricare un ⟦First Aid Kit=Kit di Primo Soccorso⟧ tutto tuo. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0x6e7c255b, 0x872ca64f, 0x32ff3188, nil, 0x3a282524, "...m." },
  [97920] = { "⟦Camping=Campeggio⟧ 101: Pesca", "Parla con Lee Brown vicino a ⟦Goldshire=Borgodoro⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Forse non lo diresti, ma la tua abilità nella Pesca può davvero tornare utile all'accampamento.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una ⟦Fish Bowl=Boccia per Pesci⟧ per il tuo accampamento. Puoi usare questo arredo per portare un po' di gioia a te e ai tuoi compagni d'avventura. Un avventuriero felice è un avventuriero forte, e di sicuro le tue capacità in combattimento lo dimostreranno.", nil, "Ecco fatto: ora puoi fabbricare una ⟦Fish Bowl=Boccia per Pesci⟧ tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0xe0c1c700, 0xc4adeb37, 0x1bcf05fd, nil, 0x54727538, "...m." },
  [97921] = { "⟦Camping=Campeggio⟧ 101: Erbalismo", "Parla con l'erbalista Pomeroy nella ⟦Elwynn Forest=Foresta di Elwynn⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Mi pare che tu abbia acquisito una certa abilità nell'Erbalismo. Raccogliere fiori non serve solo a perdere tempo, sai. Può essere utile... e redditizio.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una ⟦Incense Candle=Candela d'Incenso⟧ per il tuo accampamento. Il morale alto è fondamentale per tenere in battaglia guaritori e lanciatori di incantesimi, e una ⟦Incense Candle=Candela d'Incenso⟧ può dare una spinta che chi usa la magia apprezzerà di certo.", nil, "Ecco fatto: ora puoi fabbricare una ⟦Incense Candle=Candela d'Incenso⟧ tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0xd7cde71c, 0xd56c7091, 0xe0048777, nil, 0x52608ebe, "...m." },
  [97922] = { "⟦Camping=Campeggio⟧ 101: Conciatura", "Parla con Adele Fielder a ⟦Goldshire=Borgodoro⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Così ora lavori il cuoio. Buon per te, {class}. Mi sa che conosco qualcuno che può insegnarti a fabbricare una tenda che ti terrà al fresco nei giorni caldi e all'asciutto in quelli di pioggia.\n\nCon una buona tenda sopra la testa, avrai tutto il riposo che ti serve per restare in forma durante i tuoi viaggi.", nil, nil, 0x40d05936, 0xd01e7cfe, 0x86e620e9, nil, nil, "...mm" },
  [97923] = { "⟦Camping=Campeggio⟧ 101: Estrazione", "Parla con ⟦Gelman Stonehand=Gelman Mandipietra⟧ a ⟦Stormwind=Roccavento⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "L'Estrazione non sarà il mestiere più affascinante, ma è un lavoro onesto e una bella professione da esplorare.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Lodestone=Magnetite⟧ per il tuo accampamento. Costruiscine una e chiunque voglia menare la spada non vedrà l'ora di radunarsi attorno al tuo fuoco per assorbire quella \"grinta\" in più che può dare alla sua abilità in combattimento.", nil, "Ecco fatto: ora puoi fabbricare un ⟦Lodestone=Magnetite⟧ tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0xa8fe12f3, 0x996abb28, 0x8ef0fff6, nil, 0x0b8098cd, "...m." },
  [97924] = { "⟦Camping=Campeggio⟧ 101: Scuoiatura", "Parla con ⟦Helene Peltskinner=Helene Scuoiapelli⟧ a ⟦Goldshire=Borgodoro⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Saper ricavare con abilità pelli e cuoi dalle bestie abbattute è una delle capacità più preziose che un avventuriero possa avere.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una ⟦Camp Chair=Sedia da Campo⟧ per il tuo accampamento. A volte è importante concedersi un po' di riposo, e puoi usare alcune delle pelli che hai raccolto per farti una sedia comoda su cui sederti. Un po' di relax può aiutarti a restare in piena forma e a colpire dove conta la prossima volta che ti ritroverai in una zuffa.", nil, "Ecco fatto: ora puoi fabbricare una ⟦Camp Chair=Sedia da Campo⟧ tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0x14236b38, 0x7687adb0, 0x1755b1ba, nil, 0x98c24a76, "...m." },
  [97925] = { "⟦Camping=Campeggio⟧ 101: Sartoria", "Parla con Eldrin al ⟦Eastvale Logging Camp=Campo di Taglio di Vallevante⟧, nella ⟦Elwynn Forest=Foresta di Elwynn⟧, per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "La Sartoria è un mestiere sorprendentemente valido su cui investire, e di certo ti servirà bene.\n\nConosco qualcuno che può insegnarti a fabbricare uno ⟦Faction Banner=Stendardo della Fazione⟧ per il tuo accampamento, se hai l'abilità necessaria. Ispirazione e morale sono fondamentali per vincere su qualsiasi campo di battaglia, e uno stendardo che ispira può fare molto per tenerti carico di energie.", nil, nil, 0xde7f398c, 0x7350f5be, 0x49663bd1, nil, nil, "...mm" },
  [97926] = { "Arrangiarsi", "Porta la ⟦Alexston's Reply=Risposta di Alexston⟧ a ⟦Thundris Windweaver=Thundris Brigliavento⟧ ad Auberdine, a ⟦Darkshore=Rivafosca⟧.", "Vorrei che fosse così facile aiutare, {class}. Davvero.\n\nSe deciderai di passare più tempo nelle nostre terre, scoprirai che a molti manca tutto. Le casse di Roccavento non sono più quelle di un tempo, e quel che resta è distribuito con il contagocce.\n\nDai questa risposta all'anziano la prossima volta che lo vedi. Non è ciò che spera, ma è tutto quello che posso offrire per ora.", "Sei tornat<o/a>. Che notizie porti da ⟦Stormwind=Roccavento⟧?", "Brutte notizie davvero. Ti ringrazio comunque per aver fatto il viaggio.\n\nVisto che né ⟦Stormwind=Roccavento⟧ né Darnassus vengono in nostro aiuto, pare che il destino di Auberdine spetti a noi deciderlo.", 0xe4477319, 0xeee57b55, 0x5de57436, 0x33442a57, 0x68b57782, "....." },
  [97927] = { "⟦Camping=Campeggio⟧ 101: Alchimia", "Parla con Kray a ⟦Thunder Bluff=Picco del Tuono⟧ per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Dunque hai scelto di preparare intrugli e pozioni come alchimista. Di sicuro ti tornerà utile nei tuoi viaggi.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Mana Well=Pozzo di Mana⟧ per il tuo accampamento. Costruiscine uno e tutti i guaritori e i lanciatori di incantesimi accorreranno per gustarne un sorso rinfrescante.", nil, nil, 0x32f4ba12, 0x9fd6db54, 0xf6c52c29, nil, nil, "...mm" },
  [97928] = { "⟦Camping=Campeggio⟧ 101: Forgiatura", "Parla con ⟦Thrag Stonehoof=Thrag Zoccolo Granitico⟧ a ⟦Thunder Bluff=Picco del Tuono⟧ per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Dunque ti sei dat<o/a> alla Forgiatura. Ottima scelta, se vuoi che le tue lame non perdano mai il filo.\n\nMi sa che conosco qualcuno che può aiutarti, insegnandoti a fabbricare una ⟦Sharpening Wheel=Mola per Affilare⟧. Tirane fuori una al tuo accampamento e tutti i guerrieri e i ladri dei dintorni faranno la fila per affilare le loro armi.", nil, nil, 0x16979ea3, 0x0c123764, 0x469a706e, nil, nil, "...mm" },
  [97929] = { "⟦Camping=Campeggio⟧ 101: Incantamento", "Parla con ⟦Mot Dawnstrider=Mot Alba Lunga⟧ a ⟦Thunder Bluff=Picco del Tuono⟧ per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Gli incantatori rendono migliore ogni cosa e sono sempre i benvenuti in qualsiasi accampamento nelle terre selvagge.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Enchanted Lute=Liuto Incantato⟧ per il tuo accampamento. È importantissimo trovare un po' di svago nei momenti di riposo, e questo pizzico di magia può aiutarti a essere pront<o/a> ad affrontare ogni sorta di sfida quando riprenderai la vecchia strada polverosa.", nil, nil, 0x2e9b8c15, 0x907d3afc, 0xb4a29ffc, nil, nil, "...mm" },
  [97930] = { "⟦Camping=Campeggio⟧ 101: Ingegneria", "Parla con ⟦Twizwick Sprocketgrind=Twizwick Giramacina⟧ nella miniera della S.P.R. & Co., a Mulgore per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Gli ingegneri come te sanno inventarsi ogni sorta di congegni, robot e bombe, per divertimento e per profitto.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Reagent Bot=Robot dei Reagenti⟧ per il tuo accampamento. Questo utile automa può aiutarti a restare ben rifornit<o/a>, così tu e i tuoi alleati non resterete mai senza i materiali che servono ad alimentare i vostri incantesimi.", nil, nil, 0x1cb4025b, 0xcc961537, 0x549b28c0, nil, nil, "...mm" },
  [97931] = { "⟦Camping=Campeggio⟧ 101: ⟦First Aid=Primo Soccorso⟧", "Parla con ⟦Vira Younghoof=Vira Vento Salubre⟧ al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧ per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Quindi ti sei dat<o/a> al ⟦First Aid=Primo Soccorso⟧? È un'attività onorevole... e pragmatica per <un/una> {class}.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦First Aid Kit=Kit di Primo Soccorso⟧ per il tuo accampamento. Nella vita d'avventura le ferite sono una realtà, e offrire un po' di cure tanto necessarie al tuo accampamento potrebbe persino salvare delle vite.", nil, "Ecco fatto: ora puoi fabbricare un ⟦First Aid Kit=Kit di Primo Soccorso⟧ tutto tuo. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0x6e7c255b, 0x86c85202, 0x32ff3188, nil, 0x3a282524, "...m." },
