  [97935] = { "⟦Camping=Campeggio⟧ 101: Estrazione", "Parla con ⟦Brek Stonehoof=Brek Zoccolo Granitico⟧ a ⟦Thunder Bluff=Picco del Tuono⟧ per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "L'Estrazione non sarà il mestiere più affascinante, ma è un lavoro onesto e una bella professione da esplorare.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Lodestone=Magnetite⟧ per il tuo accampamento. Costruiscine una e chiunque voglia menare la spada non vedrà l'ora di radunarsi attorno al tuo fuoco per assorbire quella \"grinta\" in più che può dare alla sua abilità in combattimento.", nil, nil, 0xa8fe12f3, 0xab156797, 0x8ef0fff6, nil, nil, "...mm" },
