  [97961] = { "⟦Camping=Campeggio⟧ 101: Sartoria", "Parla con Bowen Brisboise sulla strada da ⟦Deathknell=Albamorta⟧ a Brill per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "La Sartoria è un mestiere sorprendentemente valido su cui investire, e di certo ti servirà bene.\n\nConosco qualcuno che può insegnarti a fabbricare uno ⟦Faction Banner=Stendardo della Fazione⟧ per il tuo accampamento, se hai l'abilità necessaria. Ispirazione e morale sono fondamentali per vincere su qualsiasi campo di battaglia, e uno stendardo che ispira può fare molto per tenerti carico di energie.", nil, nil, 0xde7f398c, 0xe62978ca, 0x49663bd1, nil, nil, "...mm" },
  [97963] = { "⟦Camping=Campeggio⟧ 101: Alchimia", "Parla con Nyassa Swiftdraught a Shen'dar Village per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Dunque hai scelto di preparare intrugli e pozioni come alchimista. Di sicuro ti tornerà utile nei tuoi viaggi.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Mana Well=Pozzo di Mana⟧ per il tuo accampamento. Costruiscine uno e tutti i guaritori e i lanciatori di incantesimi accorreranno per gustarne un sorso rinfrescante.", nil, "Ecco fatto: ora puoi fabbricare un ⟦Mana Well=Pozzo di Mana⟧ tutto tuo. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0x32f4ba12, 0x13d46d67, 0xf6c52c29, nil, 0xbd7a9e72, "...m." },
  [97964] = { "⟦Camping=Campeggio⟧ 101: Forgiatura", "Parla con Aedi Thriceforged a Shen'dar Village per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Dunque ti sei dat<o/a> alla Forgiatura. Ottima scelta, se vuoi che le tue lame non perdano mai il filo.\n\nMi sa che conosco qualcuno che può aiutarti, insegnandoti a fabbricare una ⟦Sharpening Wheel=Mola per Affilare⟧. Tirane fuori una al tuo accampamento e tutti i guerrieri e i ladri dei dintorni faranno la fila per affilare le loro armi.", nil, nil, 0x16979ea3, 0x2e5ffa5c, 0x469a706e, nil, nil, "...mm" },
  [97965] = { "⟦Camping=Campeggio⟧ 101: ⟦First Aid=Primo Soccorso⟧", "Parla con Naleeia Tattermend a Shen'dar Village per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Quindi ti sei dat<o/a> al ⟦First Aid=Primo Soccorso⟧? È un'attività onorevole... e pragmatica per <un/una> {class}.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦First Aid Kit=Kit di Primo Soccorso⟧ per il tuo accampamento. Nella vita d'avventura le ferite sono una realtà, e offrire un po' di cure tanto necessarie al tuo accampamento potrebbe persino salvare delle vite.", nil, "Ecco fatto: ora puoi fabbricare un ⟦First Aid Kit=Kit di Primo Soccorso⟧ tutto tuo. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0x6e7c255b, 0x022a7953, 0x32ff3188, nil, 0x3a282524, "...m." },
  [97967] = { "⟦Camping=Campeggio⟧ 101: Pesca", "Parla con Fenn Fairweather a Shen'dar Village per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Forse non lo diresti, ma la tua abilità nella Pesca può davvero tornare utile all'accampamento.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una ⟦Fish Bowl=Boccia per Pesci⟧ per il tuo accampamento. Puoi usare questo arredo per portare un po' di gioia a te e ai tuoi compagni d'avventura. Un avventuriero felice è un avventuriero forte, e di sicuro le tue capacità in combattimento lo dimostreranno.", nil, "Ecco fatto: ora puoi fabbricare una ⟦Fish Bowl=Boccia per Pesci⟧ tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0xe0c1c700, 0x62e07843, 0x1bcf05fd, nil, 0x54727538, "...m." },
  [97968] = { "⟦Camping=Campeggio⟧ 101: Erbalismo", "Parla con Syriel Nightrain a Valanaar per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Mi pare che tu abbia acquisito una certa abilità nell'Erbalismo. Raccogliere fiori non serve solo a perdere tempo, sai. Può essere utile... e redditizio.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una ⟦Incense Candle=Candela d'Incenso⟧ per il tuo accampamento. Il morale alto è fondamentale per tenere in battaglia guaritori e lanciatori di incantesimi, e una ⟦Incense Candle=Candela d'Incenso⟧ può dare una spinta che chi usa la magia apprezzerà di certo.", nil, "Ecco fatto: ora puoi fabbricare una ⟦Incense Candle=Candela d'Incenso⟧ tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0xd7cde71c, 0xb11f2169, 0xe0048777, nil, 0x52608ebe, "...m." },
  [97969] = { "⟦Camping=Campeggio⟧ 101: Conciatura", "Parla con ⟦Indari Sunseam=Indari Cucisole⟧ a Shen'dar Village per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Così ora lavori il cuoio. Buon per te, {class}. Mi sa che conosco qualcuno che può insegnarti a fabbricare una tenda che ti terrà al fresco nei giorni caldi e all'asciutto in quelli di pioggia.\n\nCon una buona tenda sopra la testa, avrai tutto il riposo che ti serve per restare in forma durante i tuoi viaggi.", nil, "Ecco fatto: una tenda da campo tutta tua. Alla gente non piace granché vedere tende montate in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0x40d05936, 0x02561574, 0x86e620e9, nil, 0x01530ff6, "...m." },
  [97970] = { "⟦Camping=Campeggio⟧ 101: Estrazione", "Parla con Messana Crestwind a Shen'dar Village per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "L'Estrazione non sarà il mestiere più affascinante, ma è un lavoro onesto e una bella professione da esplorare.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Lodestone=Magnetite⟧ per il tuo accampamento. Costruiscine una e chiunque voglia menare la spada non vedrà l'ora di radunarsi attorno al tuo fuoco per assorbire quella \"grinta\" in più che può dare alla sua abilità in combattimento.", nil, "Ecco fatto: ora puoi fabbricare un ⟦Lodestone=Magnetite⟧ tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0xa8fe12f3, 0x797ded19, 0x8ef0fff6, nil, 0x0b8098cd, "...m." },
  [97971] = { "⟦Camping=Campeggio⟧ 101: Scuoiatura", "Parla con Mendalass Tattermend a Shen'dar Village per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Saper ricavare con abilità pelli e cuoi dalle bestie abbattute è una delle capacità più preziose che un avventuriero possa avere.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una ⟦Camp Chair=Sedia da Campo⟧ per il tuo accampamento. A volte è importante concedersi un po' di riposo, e puoi usare alcune delle pelli che hai raccolto per farti una sedia comoda su cui sederti. Un po' di relax può aiutarti a restare in piena forma e a colpire dove conta la prossima volta che ti ritroverai in una zuffa.", nil, "Ecco fatto: ora puoi fabbricare una ⟦Camp Chair=Sedia da Campo⟧ tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0x14236b38, 0xb45769bd, 0x1755b1ba, nil, 0x98c24a76, "...m." },
  [97972] = { "⟦Camping=Campeggio⟧ 101: Sartoria", "Parla con ⟦Taleen Shimmerthread=Taleen Filolucente⟧ a Shen'dar Village per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "La Sartoria è un mestiere sorprendentemente valido su cui investire, e di certo ti servirà bene.\n\nConosco qualcuno che può insegnarti a fabbricare uno ⟦Faction Banner=Stendardo della Fazione⟧ per il tuo accampamento, se hai l'abilità necessaria. Ispirazione e morale sono fondamentali per vincere su qualsiasi campo di battaglia, e uno stendardo che ispira può fare molto per tenerti carico di energie.", nil, nil, 0xde7f398c, 0x496099ef, 0x49663bd1, nil, nil, "...mm" },
  [97973] = { "⟦Camping=Campeggio⟧ 101: Sartoria", "Parla con ⟦Taleen Shimmerthread=Taleen Filolucente⟧ a Shen'dar Village per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "La Sartoria è un mestiere sorprendentemente valido su cui investire, e di certo ti servirà bene.\n\nConosco qualcuno che può insegnarti a fabbricare uno ⟦Faction Banner=Stendardo della Fazione⟧ per il tuo accampamento, se hai l'abilità necessaria. Ispirazione e morale sono fondamentali per vincere su qualsiasi campo di battaglia, e uno stendardo che ispira può fare molto per tenerti carico di energie.", nil, nil, 0xde7f398c, 0x496099ef, 0x49663bd1, nil, nil, "...mm" },
  [97977] = { "Il richiamo della natura", "Raccogli $N1 Gnarlpine Totem e portali a Tarindrella.", "I mezzorsi ⟦Gnarlpine=Mordipigna⟧ non si sarebbero rivoltati così facilmente contro i loro antichi alleati. Dobbiamo saperne di più sulla loro sorte.\n\nCerca dei totem nelle loro case abbandonate. Se qualcuno è sopravvissuto al caos della loro partenza, le incisioni potrebbero dirci di più su ciò che è successo qui.\n\nTroverai i loro accampamenti lungo il margine occidentale della valle, anche se i grell e i grellkin potrebbero averli sparpagliati più in là.", "Non preoccuparti degli eventuali totem più grandi che potresti trovare. Non saprei che farmene, anche se trovassi un modo per portarli qui!", "Oh, è persino peggio di quanto pensassi.\n\nQueste incisioni ci dicono che i ⟦Gnarlpine=Mordipigna⟧ cominciarono ad avere incubi in cui venivano sterminati da una grande ombra. In breve quella paura si trasformò in rabbia, e l'ombra nei loro vecchi amici elfi. Rendersi conto che la propria mente sta scivolando via...\n\nLa nostra unica speranza è che questo ci aiuti a capire meglio cosa sta succedendo su Teldrassil. Grazie per il tuo aiuto, {name}.", 0x8ddb1b2f, 0x0263ede4, 0x02e09ddc, 0xc1ecd12f, 0x12ba2b7d, "....." },
  [97979] = { "La dea provvede", "Lancia Elune's Light e Shadowmeld.", "Sei nat<o/a> kaldorei, figli<o/a> delle stelle, e hai ereditato un diritto di nascita che non ha eguali in questo mondo. La grazia di Elune può illuminare la nostra forza, guidando i nostri colpi a segno, o aiutarci a nasconderci come la luna può eclissare il sole.\n\nLa nostra Lunga Veglia dopo la difesa del ⟦Mount Hyjal=Monte Hyjal⟧ è finita, e ci siamo uniti a un'⟦Alliance=Alleanza⟧ con altri popoli, che incontrerai a tempo debito. Per ora sei al riparo tra i rami di Teldrassil.\n\nDimostra i doni di Madre Luna e crogiolati nelle sue benedizioni.", nil, "Hai visto ciò che la nostra dea ci dona. Usalo bene, e lei non ti abbandonerà mai.", 0x1c2fae6f, 0x2d344d16, 0x2061ad94, nil, 0xc6da7ff1, "...m." },
  [97985] = { "Cuori tonanti", "Uccidi Stormheart a ⟦Thousand Needles=Millepicchi⟧ e prendine il cuore.", "Affascinanti, vero? È la prima volta che mi vengono svelati i segreti della creazione degli abomini.\n\nHo studiato questi appunti, e a quanto pare ci serve un cuore. Uno enorme!\n\nHo sentito dire che a ⟦Thousand Needles=Millepicchi⟧ c'è un sauro del tuono di dimensioni impressionanti, chiamato Stormheart, che pattuglia il bordo del canyon. Con un nome del genere deve avere il cuore perfetto. Devo avere quel cuore!\n\nAh, ti consiglio anche di portare degli amici. Stormheart non è noto per la sua docilità.", nil, nil, 0xf631fcf2, 0xc353cffe, 0x745e4a8c, nil, nil, "...mm" },
})
